INSERT INTO `test_form_schemas` VALUES (1,'LAB','Lab Test - Dimensions & Specifications','LAB','[{\"key\": \"engine\", \"type\": \"fields\", \"label\": \"Engine\", \"fields\": [{\"key\": \"brand_model\", \"label\": \"Name of brand with model\"}, {\"key\": \"country_of_origin\", \"label\": \"Country of origin\"}, {\"key\": \"no_of_cylinders\", \"label\": \"No of Cylinders\"}, {\"key\": \"fuel_system\", \"label\": \"Fuel system\"}, {\"key\": \"fuel_filters\", \"label\": \"Fuel filters\"}, {\"key\": \"max_gross_power_rpm\", \"label\": \"Maximum gross engine power (rpm) (Ps as per BS AU 141a)\"}, {\"key\": \"displacement_cc\", \"label\": \"Displacement (cc)\"}, {\"key\": \"rated_speed_rpm\", \"label\": \"Rated speed (rpm)\"}, {\"key\": \"bore_mm\", \"label\": \"Bore (mm)\"}, {\"key\": \"stroke_mm\", \"label\": \"Stroke (mm)\"}, {\"key\": \"max_gross_torque\", \"label\": \"Max. Gross engine torque (rpm) (kgm)\"}, {\"key\": \"air_cleaner_system\", \"label\": \"Air cleaner system\"}, {\"key\": \"exhaust\", \"label\": \"Exhaust\"}, {\"key\": \"cooling_system\", \"label\": \"Engine cooling system\"}, {\"key\": \"throttle_control\", \"label\": \"Throttle control\"}, {\"key\": \"oil_change_interval\", \"label\": \"Engine oil change interval\"}, {\"key\": \"aspiration\", \"label\": \"Aspiration\"}]}, {\"key\": \"clutch\", \"type\": \"fields\", \"label\": \"Clutch\", \"fields\": [{\"key\": \"type\", \"label\": \"Type\"}, {\"key\": \"diameter\", \"label\": \"Diameter\"}, {\"key\": \"method_operation\", \"label\": \"Method operation\"}]}, {\"key\": \"transmission\", \"type\": \"fields\", \"label\": \"Transmission\", \"fields\": [{\"key\": \"transmission_type\", \"label\": \"Transmission type\"}, {\"key\": \"no_of_speed\", \"label\": \"No. of speed\"}, {\"key\": \"shifting\", \"label\": \"Shifting\"}]}, {\"key\": \"rear_axle\", \"type\": \"fields\", \"label\": \"Rear axle & final drive\", \"fields\": [{\"key\": \"type\", \"label\": \"Type\"}, {\"key\": \"std_track\", \"label\": \"R