--
-- Table structure for table `test_records`
--

DROP TABLE IF EXISTS `test_records`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `test_records` (
  `test_id` int NOT NULL AUTO_INCREMENT,
  `machine_id` int NOT NULL,
  `test_name` varchar(100) NOT NULL,
  `is_field_test` tinyint(1) DEFAULT '1',
  `requires_water` tinyint(1) DEFAULT '0',
  `required_season` enum('Ploughing','Harvesting','Any') DEFAULT 'Any',
  `technical_assistant_id` int DEFAULT NULL,
  `mechanical_engineer_id` int DEFAULT NULL,
  `chief_engineer_id` int DEFAULT NULL,
  `schema_id` int DEFAULT NULL,
  `form_data` json DEFAULT NULL,
  `status` enum('Draft','Submitted','Reviewed','Approved','Rejected') DEFAULT 'Draft',
  `me_recommendation` enum('Pending','Recommended','Not Recommended') DEFAULT 'Pending',
  `me_comments` text,
  `ce_comments` text,
  `submitted_at` timestamp NULL DEFAULT NULL,
  `reviewed_at` timestamp NULL DEFAULT NULL,
  `approved_at` timestamp NULL DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `include_in_final_report` tinyint(1) DEFAULT '0',
  `group_key` varchar(50) DEFAULT NULL,
  `catalog_key` varchar(50) DEFAULT NULL,
  `reschedule_requested` tinyint(1) DEFAULT '0',
  `reschedule_reason` text,
  `me_review_progress` json DEFAULT NULL,
  PRIMARY KEY (`test_id`),
  KEY `machine_id` (`machine_id`),
  KEY `technical_assistant_id` (`technical_assistant_id`),
  KEY `mechanical_engineer_id` (`mechanical_engineer_id`),
  KEY `chief_engineer_id` (`chief_engineer_id`),
  KEY `fk_test_records_schema` (`schema_id`),
  CONSTRAINT `fk_test_records_schema` FOREIGN KEY (`schema_id`) REFERENCES `test_form_schemas` (`schema_id`) ON DELETE SET NULL,
  CONSTRAINT `test_records_ibfk_1` FOREIGN KEY (`machine_id`) REFERENCES `machinery` (`machine_id`) ON DELETE CASCADE,
